package com.interviewiq.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.interviewiq.ai.AIService;import com.interviewiq.api.AssessmentDtos.*;import com.interviewiq.domain.*;import com.interviewiq.repository.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.util.*;import java.util.stream.Collectors;
@Service public class AssessmentService {
 private final AssessmentRepository assessments;private final QuestionRepository questions;private final ObjectMapper mapper;private final AIService ai;private final ScoringPolicy scoring;
 public AssessmentService(AssessmentRepository a,QuestionRepository q,ObjectMapper m,AIService ai,ScoringPolicy scoring){assessments=a;questions=q;mapper=m;this.ai=ai;this.scoring=scoring;}
 @Transactional public AssessmentView create(AppUser user,CreateRequest req){int count=req.questionCount()==null?10:Math.min(30,Math.max(5,req.questionCount()));String role=blank(req.targetRole())?user.getTargetRole():req.targetRole();var types=req.types()==null?List.of("MCQ","TECHNICAL","BEHAVIORAL"):req.types();var generated=ai.generate(role==null?"Software Developer":role,req.difficulty()==null?"Mixed":req.difficulty(),req.topics()==null?List.of():req.topics(),count,types,user.getExperienceLevel()==null?"Fresher":user.getExperienceLevel());if(!generated.isEmpty()){questions.saveAll(generated);}var pool=new ArrayList<>(generated.isEmpty()?questions.findByActiveTrue():generated);if(req.topics()!=null&&!req.topics().isEmpty())pool.removeIf(q->!req.topics().contains(q.getTopic()));Collections.shuffle(pool);if(pool.isEmpty())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"No questions are available for these topics yet.");var selected=pool.stream().limit(count).toList();var a=assessments.save(new Assessment(user,"Interview Readiness Assessment",role,selected));return view(a);}
 public List<AssessmentView> history(AppUser user){return assessments.findByUserIdOrderByCreatedAtDesc(user.getId()).stream().map(this::view).toList();}
 public AssessmentView get(AppUser user,Long id){return view(owned(user,id));}
 @Transactional public Map<String,Object> submit(AppUser user,Long id,SubmitRequest request){Assessment a=owned(user,id);if(a.getScore()!=null)throw new ResponseStatusException(HttpStatus.CONFLICT,"This assessment was already submitted.");Map<Long,String> answers=request.answers()==null?Map.of():request.answers();int correct=0,objective=0,openScore=0,openCount=0;Map<String,int[]> topic=new LinkedHashMap<>();List<Map<String,Object>> feedback=new ArrayList<>();
  for(Question q:a.getQuestions()){String answer=answers.getOrDefault(q.getId(),"").trim();boolean mcq=q.getType().equals("MCQ")||q.getType().equals("TRUE_FALSE");var expected=q.getExpectedConcepts()==null?List.<String>of():Arrays.stream(q.getExpectedConcepts().split(",")).map(String::trim).filter(s->!s.isBlank()).toList();boolean hit=false;int pts=0;Map<String,Object> aiFeedback=Map.of();if(mcq){objective++;hit=!answer.isBlank()&&q.getCorrectAnswer()!=null&&answer.equalsIgnoreCase(q.getCorrectAnswer());if(hit)correct++;pts=hit?100:0;}else{openCount++;aiFeedback=ai.evaluate(q.getPrompt(),q.getExpectedConcepts(),answer,q.getType().equals("BEHAVIORAL"));long matches=expected.stream().filter(c->answer.toLowerCase().contains(c.toLowerCase())).count();int fallback=answer.isBlank()?0:expected.isEmpty()?55:(int)Math.round(Math.min(100,35+65.0*matches/expected.size()));pts=aiFeedback.get("score") instanceof Number n?n.intValue():fallback;openScore+=pts;}
   topic.computeIfAbsent(q.getTopic(),k->new int[2]);topic.get(q.getTopic())[0]+=pts;topic.get(q.getTopic())[1]++;
   Map<String,Object> row=new LinkedHashMap<>();row.put("questionId",q.getId());row.put("score",pts);row.put("correct",hit);row.put("feedback",mcq?(hit?"Correct answer.":"Review the explanation and try this topic again."):answer.isBlank()?"Add an answer next time; unanswered responses receive no credit.":aiFeedback.getOrDefault("feedback","Your response was reviewed against key concepts. Expand the explanation with concrete examples."));row.put("missingConcepts",mcq?List.of():aiFeedback.getOrDefault("missingConcepts",expected.stream().filter(c->!answer.toLowerCase().contains(c.toLowerCase())).toList()));row.put("strengths",aiFeedback.getOrDefault("strengths",List.of()));row.put("improvements",aiFeedback.getOrDefault("improvements",List.of()));feedback.add(row);
  }
  int mcqScore=objective==0?0:(int)Math.round(correct*100.0/objective);int written= openCount==0?0:(int)Math.round(openScore*1.0/openCount);int score=scoring.combine(mcqScore,written,objective>0,openCount>0);Map<String,Integer> skills=topic.entrySet().stream().collect(Collectors.toMap(Map.Entry::getKey,e->(int)Math.round(e.getValue()[0]*1.0/e.getValue()[1]),(x,y)->x,LinkedHashMap::new));List<String> strengths=skills.entrySet().stream().filter(e->scoring.classify(e.getValue()).equals("Strong")).map(Map.Entry::getKey).toList();List<String> weak=skills.entrySet().stream().filter(e->!scoring.classify(e.getValue()).equals("Strong")).map(Map.Entry::getKey).toList();Map<String,Object> result=new LinkedHashMap<>();result.put("assessmentId",a.getId());result.put("score",score);result.put("correct",correct);result.put("objectiveCount",objective);result.put("skillScores",skills);result.put("strengths",strengths);result.put("improvements",weak);result.put("feedback",score>=75?"Strong foundation. Keep practicing the areas below to build interview confidence.":"A useful baseline. Focus on one improvement area at a time, then reassess to track your progress.");result.put("answers",feedback);a.setScore(score);try{a.setResultJson(mapper.writeValueAsString(result));}catch(Exception ex){throw new IllegalStateException(ex);}assessments.save(a);return result;
 }
 public Map<String,Object> result(AppUser user,Long id){Assessment a=owned(user,id);if(a.getResultJson()==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Submit the assessment to view its result.");try{return mapper.readValue(a.getResultJson(),Map.class);}catch(Exception e){throw new IllegalStateException(e);}}
 private Assessment owned(AppUser u,Long id){return assessments.findById(id).filter(a->a.getUser().getId().equals(u.getId())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Assessment not found."));}
 private AssessmentView view(Assessment a){return new AssessmentView(a.getId(),a.getTitle(),a.getTargetRole(),a.getQuestionCount(),a.getQuestions().stream().map(q->new QuestionView(q.getId(),q.getPrompt(),q.getType(),q.getTopic(),q.getDifficulty(),q.getOptions())).toList(),a.getScore(),a.getCreatedAt()==null?null:a.getCreatedAt().toString());}
 private boolean blank(String s){return s==null||s.isBlank();}
}
